// The site has two sidebars. Both are passed to Starlight as one list;
// src/routeData.ts shows only the one the current page belongs to.

const page = (label, link, icon) => ({ label, link, attrs: { class: `td-icon td-icon-${icon}` } });
const external = (label, link, icon) => ({
  label,
  link,
  attrs: { class: `td-icon td-icon-${icon} td-external`, target: '_blank', rel: 'noopener' },
});

/** @param {any[]} apiReference the groups generated by starlight-openapi */
export const developerSidebar = (apiReference) => [
  {
    label: 'Getting started',
    items: [
      page('Home', '/start/', 'home'),
      page('What is TrustDeck?', '/overview/', 'book'),
      page('Quickstart', '/quickstart/', 'play'),
      page('Glossary', '/glossary/', 'list'),
    ],
  },
  {
    label: 'REST API',
    items: [
      page('Authentication', '/rest-api/authentication/', 'key'),
      page('All endpoints', '/rest-api/endpoints/', 'list'),
      page('Errors and status codes', '/rest-api/errors/', 'flag'),
    ],
  },
  {
    label: 'Java client',
    items: [
      page('Getting started', '/java-client/getting-started/', 'package'),
      page('Usage', '/java-client/usage/', 'code'),
      page('Permissions', '/java-client/permissions/', 'users'),
      external('Javadoc', 'https://javadoc.io/doc/org.trustdeck/client/2.1.0', 'book'),
    ],
  },
  { label: 'Concepts', items: [page('Core concepts', '/concepts/', 'layers')] },
  ...apiReference,
  { label: 'Deploy and operate', items: [page('Deploy', '/deploy/', 'server')] },
];

export const userSidebar = [
  {
    label: 'User guide',
    items: [page('Introduction', '/user/', 'home'), page('Project overview', '/user/project-overview/', 'list')],
  },
  {
    label: 'Projects',
    items: [
      page('Create a project', '/user/create-project/', 'plus'),
      page('Create a group', '/user/create-group/', 'layers'),
      page('Create and edit entities', '/user/entities/', 'package'),
    ],
  },
  {
    label: 'Permissions',
    items: [
      page('Global permissions', '/user/global-permissions/', 'key'),
      page('Project permissions', '/user/project-permissions/', 'users'),
    ],
  },
];
